-- Rollback for Sprint 237g: restores the exact anon/authenticated table and column ACLs captured live on
-- 2026-10-16 before 237g (930 table-privilege entries, 18 column grants), after 237d/237e/237f. Not a migration;
-- run manually as postgres only if 237g must be undone. Intentionally preserves 237d/237e locks (they are part of the
-- snapshot) instead of re-granting everything.
begin;
drop trigger if exists rent_charges_guard_client_write on public.rent_charges;
drop function if exists public.guard_client_rent_charge_write();
do $$
declare t record;
begin
  for t in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
           where n.nspname = 'public' and c.relkind in ('r', 'p') loop
    execute format('revoke all on table public.%I from anon, authenticated', t.relname);
  end loop;
end $$;
